  const latestCommitSha = refData.object?.sha;

  if (!latestCommitSha) {
    return {
      errorResponse: NextResponse.json(
        { error: 'Could not resolve latest commit SHA from branch.' },
        { status: 500 }
      ),
    };
  }

  return { sha: latestCommitSha };
